contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public payable {
        uint64 beforeNumber = c.number();
        uint64 beforeTimestamp = c.timestamp();
        uint256 beforeBasefee = c.basefee();
        bytes32 beforeHash = c.hash();
        uint64 beforeSequenceNumber = c.sequenceNumber();
        bytes32 beforeBatcherHash = c.batcherHash();
        uint256 beforeL1FeeOverhead = c.l1FeeOverhead();
        uint256 beforeL1FeeScalar = c.l1FeeScalar();
        uint256 beforeBalance = address(c).balance;
        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && c.number() == beforeNumber && c.timestamp() == beforeTimestamp && c.basefee() == beforeBasefee && c.hash() == beforeHash && c.sequenceNumber() == beforeSequenceNumber && c.batcherHash() == beforeBatcherHash && c.l1FeeOverhead() == beforeL1FeeOverhead && c.l1FeeScalar() == beforeL1FeeScalar && address(c).balance == beforeBalance);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        // Setup: ensure initial L1 block values are deterministic and not the target values.
        // No direct setup call is possible for a non-depositor; depositor status is fixed.
        uint64 numberBefore = c.number();
        uint64 timestampBefore = c.timestamp();
        uint256 basefeeBefore = c.basefee();
        bytes32 hashBefore = c.hash();
        uint64 sequenceNumberBefore = c.sequenceNumber();
        bytes32 batcherHashBefore = c.batcherHash();
        uint256 l1FeeOverheadBefore = c.l1FeeOverhead();
        uint256 l1FeeScalarBefore = c.l1FeeScalar();

        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The depositor can only be msg.sender if this test contract happens to equal the hard-coded depositor.
        // For any other caller (the general case), the call must revert and all public values must be unchanged.
        if (msg.sender != c.depositorAccount()) {
            assert(reverted);
            assert(c.number() == numberBefore);
            assert(c.timestamp() == timestampBefore);
            assert(c.basefee() == basefeeBefore);
            assert(c.hash() == hashBefore);
            assert(c.sequenceNumber() == sequenceNumberBefore);
            assert(c.batcherHash() == batcherHashBefore);
            assert(c.l1FeeOverhead() == l1FeeOverheadBefore);
            assert(c.l1FeeScalar() == l1FeeScalarBefore);
        } else {
            // When the caller is the depositor, the call must succeed and still not modify any public value.
            assert(!reverted);
            assert(c.number() == numberBefore);
            assert(c.timestamp() == timestampBefore);
            assert(c.basefee() == basefeeBefore);
            assert(c.hash() == hashBefore);
            assert(c.sequenceNumber() == sequenceNumberBefore);
            assert(c.batcherHash() == batcherHashBefore);
            assert(c.l1FeeOverhead() == l1FeeOverheadBefore);
            assert(c.l1FeeScalar() == l1FeeScalarBefore);
        }
    }

    receive() external payable {}
}

